255	    @Override
256	    @Transactional
257	    public void saveOwner(Owner owner) throws DataAccessException {
258	        if (owner.isNew()) {
259	            LocalDate effectiveDate = owner.getRegistrationDate() != null
260	                ? owner.getRegistrationDate()
261	                : LocalDate.now();
262	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
263	            if (owner.getCustomerCode() == null) {
264	                owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
265	            }
266	            if (owner.getNamesakeCount() == null) {
267	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
268	            }
269	        }
270	        ownerRepository.save(owner);
271	        populateHouseholdMemberCount(owner);
272	    }
273	
274	    /**
275	     * Count the existing owners (before this create) that share the given first and last name,
276	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
277	     */
278	    private int countNamesakes(String firstName, String lastName) {
279	        if (firstName == null || lastName == null) {
280	            return 0;
281	        }
282	        return (int) ownerRepository.findAll().stream()
283	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
284	                && lastName.equalsIgnoreCase(owner.getLastName()))
285	            .count();
286	    }
287	
288	    /**
289	     * Build a customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3}
290	     * is the upper-cased first three letters of the owner's city, {@code LAST3} the
291	     * upper-cased first three letters of the owner's last name and {@code NNNN} a per-city,
292	     * 4-digit zero-padded sequence equal to one more than the current number of owners
293	     * already in that city (e.g. {@code 'LON-SMI-0007'}).
294	     */
295	    private String generateCustomerCode(String city, String lastName) {
296	        String cityName = city == null ? "" : city;
297	        String city3 = cityName.substring(0, Math.min(3, cityName.length())).toUpperCase();
298	        String name = lastName == null ? "" : lastName;
299	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
300	        long sequence = countOwnersInCity(cityName) + 1L;
301	        return String.format("%s-%s-%04d", city3, last3, sequence);
302	    }
303	
304	    /**
305	     * Count the existing owners whose city matches the given city, compared case-insensitively,
306	     * used to derive the per-city sequence of the customer code.
307	     */
308	    private long countOwnersInCity(String city) {
309	        if (city == null) {
310	            return 0L;
311	        }
312	        return ownerRepository.findAll().stream()
313	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
314	            .count();
315	    }
