329	    @Override
330	    @Transactional(readOnly = true)
331	    public boolean isBulkSignupDay() throws DataAccessException {
332	        return countRegisteredToday() > BULK_SIGNUP_THRESHOLD;
333	    }
334	
335	    /**
336	     * Count the owners whose registration date equals today's business day, used by the
337	     * daily create-limit and bulk-signup rules.
338	     */
339	    private long countRegisteredToday() {
340	        LocalDate businessDay = toBusinessDay(LocalDate.now());
341	        return ownerRepository.findAll().stream()
342	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
343	            .count();
344	    }
345	
346	    /**
347	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced
348	     * to the following Monday, while a weekday is returned unchanged. Applied to the effective
349	     * registration date (whether supplied or defaulted to the server date) so that the stored
350	     * {@code registrationDate}, every value derived from it (such as the membership number's year
351	     * segment) and the per-day create-limit all use the adjusted business day.
352	     */
353	    private static LocalDate toBusinessDay(LocalDate date) {
354	        DayOfWeek day = date.getDayOfWeek();
355	        if (day == DayOfWeek.SATURDAY) {
356	            return date.plusDays(2);
357	        }
358	        if (day == DayOfWeek.SUNDAY) {
359	            return date.plusDays(1);
360	        }
361	        return date;
362	    }
363	
364	    @Override
365	    @Transactional(readOnly = true)
366	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
367	        String normalized = normalizeTelephone(telephone);
368	        if (normalized == null) {
369	            return false;
370	        }
371	        return ownerRepository.findAll().stream()
372	            .map(owner -> normalizeTelephone(owner.getTelephone()))
373	            .anyMatch(normalized::equals);
374	    }
375	
376	    @Override
377	    @Transactional(readOnly = true)
378	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
379	        String normalizedLastName = normalizeHouseholdValue(lastName);
380	        String normalizedAddress = normalizeHouseholdAddress(address);
381	        if (normalizedLastName.isEmpty() || normalizedAddress.isEmpty()) {
382	            return false;
383	        }
384	        return ownerRepository.findAll().stream()
385	            .anyMatch(owner -> normalizedLastName.equals(normalizeHouseholdValue(owner.getLastName()))
386	                && normalizedAddress.equals(normalizeHouseholdAddress(owner.getAddress())));
387	    }
388	
389	    @Override
390	    @Transactional(readOnly = true)
391	    public String householdIdFor(String lastName, String address) throws DataAccessException {
392	        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
393	        try {
394	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
395	            StringBuilder sb = new StringBuilder(32);
396	            for (int i = 0; i < 8; i++) {
397	                sb.append(String.format("%02X", digest[i]));
398	            }
399	            return sb.toString();
400	        } catch (NoSuchAlgorithmException ex) {
401	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
402	        }
403	    }
404	
405	    /**
406	     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
407	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
408	     * spaced but equivalent values compare equal.
409	     */
410	    private static String normalizeHouseholdValue(String value) {
411	        if (value == null) {
412	            return "";
413	        }
414	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
415	    }
416	
417	    /**
418	     * Normalizes an address for household comparison by first applying the canonical address
419	     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
420	     * then the shared household-value normalization, so every address comparison uses the same
421	     * normalized form regardless of how the value was originally supplied.
422	     */
423	    private static String normalizeHouseholdAddress(String address) {
424	        return normalizeHouseholdValue(AddressNormalizer.normalize(address));
425	    }
426	
427	    /**
428	     * Populate the given owner's transient {@code householdMemberCount} with the current number of
429	     * owners that share its {@code householdId}, so the derived {@code membershipTier} reflects the
430	     * household size (3 or more members earns {@code GOLD}). Owners without a household id are left
431	     * at a count of zero.
432	     */
433	    private void populateHouseholdMemberCount(Owner owner) {
434	        if (owner == null) {
435	            return;
436	        }
437	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
438	    }
439	
440	    /**
441	     * Count the owners that belong to the household identified by the given id. Returns 0 when the
442	     * id is {@code null}, so owners that do not share a household never reach the {@code GOLD}
443	     * threshold.
444	     */
445	    private int countHouseholdMembers(String householdId) {
446	        if (householdId == null) {
447	            return 0;
448	        }
449	        return (int) ownerRepository.findAll().stream()
450	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
451	            .count();
452	    }
453	
454	    /**
455	     * Reduces a telephone number to its canonical E.164 form so that differently formatted but
456	     * equivalent numbers compare equal. A value already stored that cannot form valid E.164
457	     * (e.g. unusual legacy data) falls back to its digits-only form rather than failing lookup.
458	     */
459	    private static String normalizeTelephone(String telephone) {
460	        if (telephone == null) {
461	            return null;
462	        }
463	        try {
464	            return TelephoneNormalizer.toE164(telephone);
465	        } catch (InvalidTelephoneException ex) {
466	            return telephone.replaceAll("\\D", "");
467	        }
468	    }
