472	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
473	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
474	        owners.forEach(this::populateHouseholdMemberCount);
475	        return owners;
476	    }
