484	    @Override
485	    @Transactional(readOnly = true)
486	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
487	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
488	    }
489	
490	    private <T> T findEntityById(Supplier<T> supplier) {
491	        try {
492	            return supplier.get();
493	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
494	            // Just ignore not found exceptions for Jdbc/Jpa realization
495	            return null;
496	        }
497	    }
498	
499	}
